INSERT INTO Building_YieldChanges(BuildingType,YieldType,Yield) SELECT 'BUILDING_TERRA_MULTIMODAL_HUB','YIELD_CULTURE',0 WHERE NOT EXISTS(SELECT 1 FROM Building_YieldChanges WHERE BuildingType='BUILDING_TERRA_MULTIMODAL_HUB' AND YieldType='YIELD_CULTURE');
