INSERT INTO Leader_Flavors SELECT 'LEADER_GPT_TERRA',Type,CASE Type WHEN 'FLAVOR_EXPANSION' THEN 6 WHEN 'FLAVOR_GROWTH' THEN 6 WHEN 'FLAVOR_PRODUCTION' THEN 7 WHEN 'FLAVOR_SCIENCE' THEN 7 WHEN 'FLAVOR_GOLD' THEN 7 WHEN 'FLAVOR_CULTURE' THEN 6 WHEN 'FLAVOR_RELIGION' THEN 5 WHEN 'FLAVOR_OFFENSE' THEN 6 WHEN 'FLAVOR_DEFENSE' THEN 7 WHEN 'FLAVOR_MOBILE' THEN 6 WHEN 'FLAVOR_RANGED' THEN 6 WHEN 'FLAVOR_WONDER' THEN 5 WHEN 'FLAVOR_DIPLOMACY' THEN 7 WHEN 'FLAVOR_HAPPINESS' THEN 6 WHEN 'FLAVOR_RECON' THEN 5 WHEN 'FLAVOR_NAVAL' THEN 5 WHEN 'FLAVOR_AIR' THEN 5 WHEN 'FLAVOR_TILE_IMPROVEMENT' THEN 7 ELSE 5 END FROM Flavors;
INSERT INTO Leader_MajorCivApproachBiases SELECT 'LEADER_GPT_TERRA',MajorCivApproachType,5 FROM Leader_MajorCivApproachBiases WHERE LeaderType='LEADER_WASHINGTON';
INSERT INTO Leader_MinorCivApproachBiases SELECT 'LEADER_GPT_TERRA',MinorCivApproachType,5 FROM Leader_MinorCivApproachBiases WHERE LeaderType='LEADER_WASHINGTON';
